-- Hotel MVP Phase 0/1 security foundation. Money evidence is append-only and all
-- operational tables are protected by organization + selected-property RLS.
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TYPE "HotelReservationStatus" AS ENUM ('HOLD','CONFIRMED','CHECKED_IN','CHECKED_OUT','CANCELLED','NO_SHOW');
CREATE TYPE "HotelReservationSource" AS ENUM ('WALK_IN','PHONE','EMAIL','DIRECT');
CREATE TYPE "HotelRoomAssignmentStatus" AS ENUM ('HELD','ACTIVE','RELEASED');
CREATE TYPE "HotelReservationEventKind" AS ENUM ('CREATED','CONFIRMED','ROOM_ASSIGNED','ROOM_CHANGED','CHECKED_IN','CHECKED_OUT','CANCELLED','NO_SHOW','NOTE_ADDED');
CREATE TYPE "HotelFolioStatus" AS ENUM ('OPEN','CLOSED','VOID');
CREATE TYPE "HotelFolioPostingKind" AS ENUM ('ROOM','EXTRA','TAX','DISCOUNT','ADJUSTMENT','REVERSAL');
CREATE TYPE "HotelFolioSourceKind" AS ENUM ('NIGHT_AUDIT','HOTEL_EXTRA','MANUAL','REVERSAL');
CREATE TYPE "HotelTenderType" AS ENUM ('CASH','CARD'); CREATE TYPE "HotelPaymentDirection" AS ENUM ('COLLECTION','REFUND');
CREATE TYPE "HotelPaymentAttemptStatus" AS ENUM ('PENDING','SUCCEEDED','FAILED','CANCELLED');
CREATE TYPE "HotelPaymentEventKind" AS ENUM ('REQUESTED','AUTHORIZED','SETTLED','FAILED','CANCELLED','REFUNDED');
CREATE TYPE "HotelNightAuditStatus" AS ENUM ('RUNNING','COMPLETED','FAILED');
CREATE TYPE "HotelNightAuditStep" AS ENUM ('PRECHECK','NO_SHOWS','ROOM_POSTINGS','BALANCES','ADVANCE_DATE');
CREATE TYPE "HotelNightAuditStepStatus" AS ENUM ('PENDING','RUNNING','COMPLETED','FAILED');
ALTER TABLE "hotel_properties" ADD COLUMN "businessDate" date;

CREATE TABLE "hotel_rate_plans" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"roomTypeId" text NOT NULL,"code" text NOT NULL,"name" text NOT NULL,"nightlyRateMinor" integer NOT NULL CHECK ("nightlyRateMinor">=0),"taxConfig" jsonb NOT NULL,"currency" text NOT NULL,"active" boolean NOT NULL DEFAULT true,"validFrom" date NOT NULL,"validTo" date,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId","branchId","id"),UNIQUE("organizationId","branchId","code"),FOREIGN KEY("organizationId","branchId") REFERENCES "hotel_properties"("organizationId","branchId"),FOREIGN KEY("organizationId","branchId","roomTypeId") REFERENCES "hotel_room_types"("organizationId","branchId","id"));
CREATE TABLE "hotel_guests" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"firstName" text NOT NULL,"lastName" text NOT NULL,"email" text,"phone" text,"countryCode" text,"notes" text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId","branchId","id"),FOREIGN KEY("organizationId","branchId") REFERENCES "hotel_properties"("organizationId","branchId"));
CREATE TABLE "hotel_reservations" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"confirmationNumber" text NOT NULL,"status" "HotelReservationStatus" NOT NULL DEFAULT 'HOLD',"source" "HotelReservationSource" NOT NULL,"primaryGuestId" text NOT NULL,"arrivalDate" date NOT NULL,"departureDate" date NOT NULL,"adults" integer NOT NULL,"children" integer NOT NULL DEFAULT 0,"specialRequests" text,"currency" text NOT NULL,"bookedAt" timestamptz NOT NULL DEFAULT now(),"cancelledAt" timestamptz,"checkedInAt" timestamptz,"checkedOutAt" timestamptz,"noShowAt" timestamptz,"version" integer NOT NULL DEFAULT 1,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),CHECK("departureDate">"arrivalDate" AND "adults">0 AND "children">=0),UNIQUE("organizationId","branchId","id"),UNIQUE("organizationId","branchId","confirmationNumber"),FOREIGN KEY("organizationId","branchId","primaryGuestId") REFERENCES "hotel_guests"("organizationId","branchId","id"));
CREATE TABLE "hotel_reservation_stay_units" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"reservationId" text NOT NULL,"roomTypeId" text NOT NULL,"ratePlanId" text NOT NULL,"mealPlanId" text,"quantity" integer NOT NULL DEFAULT 1 CHECK("quantity"=1),"adults" integer NOT NULL,"children" integer NOT NULL DEFAULT 0,"nightlyRateMinor" integer NOT NULL,"netMinorPerNight" integer NOT NULL,"taxMinorPerNight" integer NOT NULL,"totalMinorPerNight" integer NOT NULL,"taxSnapshot" jsonb NOT NULL,"currency" text NOT NULL,"arrivalDate" date NOT NULL,"departureDate" date NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId","branchId","id"),FOREIGN KEY("organizationId","branchId","reservationId") REFERENCES "hotel_reservations"("organizationId","branchId","id"),FOREIGN KEY("organizationId","branchId","ratePlanId") REFERENCES "hotel_rate_plans"("organizationId","branchId","id"));
CREATE TABLE "hotel_room_assignments" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"stayUnitId" text NOT NULL,"roomId" text NOT NULL,"bedId" text,"startDate" date NOT NULL,"endDate" date NOT NULL,"status" "HotelRoomAssignmentStatus" NOT NULL DEFAULT 'HELD',"assignedAt" timestamptz NOT NULL DEFAULT now(),"assignedById" text NOT NULL,"releasedAt" timestamptz,"releaseReason" text,UNIQUE("organizationId","branchId","id"),FOREIGN KEY("organizationId","branchId","stayUnitId") REFERENCES "hotel_reservation_stay_units"("organizationId","branchId","id"));
ALTER TABLE "hotel_room_assignments" ADD CONSTRAINT hotel_room_assignments_no_overlap EXCLUDE USING gist ("organizationId" WITH =,"branchId" WITH =,"roomId" WITH =,daterange("startDate","endDate",'[)') WITH &&) WHERE ("status" IN ('HELD','ACTIVE'));
CREATE TABLE "hotel_reservation_events" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"reservationId" text NOT NULL,"kind" "HotelReservationEventKind" NOT NULL,"fromStatus" "HotelReservationStatus","toStatus" "HotelReservationStatus","actorId" text NOT NULL,"occurredAt" timestamptz NOT NULL DEFAULT now(),"reason" text,"metadata" jsonb NOT NULL DEFAULT '{}',FOREIGN KEY("organizationId","branchId","reservationId") REFERENCES "hotel_reservations"("organizationId","branchId","id"));
CREATE TABLE "hotel_confirmation_number_sequences" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"nextNumber" integer NOT NULL DEFAULT 1,UNIQUE("organizationId","branchId"));
CREATE TABLE "hotel_operation_idempotency_keys" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"scope" text NOT NULL,"key" text NOT NULL,"requestHash" text NOT NULL,"resultType" text,"resultId" text,"response" jsonb,"createdAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId","branchId","scope","key"));
CREATE TABLE "hotel_folios" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"reservationId" text NOT NULL UNIQUE,"folioNumber" text NOT NULL,"status" "HotelFolioStatus" NOT NULL DEFAULT 'OPEN',"guestId" text NOT NULL,"currency" text NOT NULL,"openedAt" timestamptz NOT NULL DEFAULT now(),"closedAt" timestamptz,"version" integer NOT NULL DEFAULT 1,UNIQUE("organizationId","branchId","id"),UNIQUE("organizationId","branchId","folioNumber"));
CREATE TABLE "hotel_folio_postings" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"folioId" text NOT NULL,"kind" "HotelFolioPostingKind" NOT NULL,"sourceKind" "HotelFolioSourceKind" NOT NULL,"sourceId" text,"reversesPostingId" text,"serviceDate" date NOT NULL,"description" text NOT NULL,"quantity" integer NOT NULL,"unitAmountMinor" integer NOT NULL,"netMinor" integer NOT NULL,"taxMinor" integer NOT NULL,"totalMinor" integer NOT NULL,"currency" text NOT NULL,"postedAt" timestamptz NOT NULL DEFAULT now(),"postedById" text NOT NULL,"reason" text,UNIQUE("organizationId","branchId","id"),UNIQUE("organizationId","branchId","sourceKind","sourceId"),FOREIGN KEY("organizationId","branchId","folioId") REFERENCES "hotel_folios"("organizationId","branchId","id"));
CREATE TABLE "hotel_folio_payments" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"folioId" text NOT NULL,"receiptNumber" text NOT NULL,"tenderType" "HotelTenderType" NOT NULL,"direction" "HotelPaymentDirection" NOT NULL,"amountMinor" integer NOT NULL CHECK("amountMinor">0),"currency" text NOT NULL,"refundsPaymentId" text,"settledAt" timestamptz NOT NULL DEFAULT now(),"settledById" text NOT NULL,UNIQUE("organizationId","branchId","id"),UNIQUE("organizationId","branchId","receiptNumber"));
CREATE TABLE "hotel_payment_attempts" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"folioId" text NOT NULL,"tenderType" "HotelTenderType" NOT NULL,"direction" "HotelPaymentDirection" NOT NULL,"status" "HotelPaymentAttemptStatus" NOT NULL,"amountMinor" integer NOT NULL,"currency" text NOT NULL,"provider" text,"externalReference" text,"requestedById" text NOT NULL,"failureCode" text,"failureMessage" text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId","branchId","id"));
CREATE TABLE "hotel_payment_events" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"paymentAttemptId" text NOT NULL,"kind" "HotelPaymentEventKind" NOT NULL,"occurredAt" timestamptz NOT NULL DEFAULT now(),"providerReference" text,"metadata" jsonb NOT NULL DEFAULT '{}');

CREATE FUNCTION hotel_reject_immutable_money() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'hotel financial evidence is append-only' USING ERRCODE='55000'; END $$;
CREATE TRIGGER hotel_rate_snapshot_immutable BEFORE UPDATE OR DELETE ON "hotel_reservation_stay_units" FOR EACH ROW EXECUTE FUNCTION hotel_reject_immutable_money();
CREATE TRIGGER hotel_posting_immutable BEFORE UPDATE OR DELETE ON "hotel_folio_postings" FOR EACH ROW EXECUTE FUNCTION hotel_reject_immutable_money();
CREATE TRIGGER hotel_payment_immutable BEFORE UPDATE OR DELETE ON "hotel_folio_payments" FOR EACH ROW EXECUTE FUNCTION hotel_reject_immutable_money();
CREATE TRIGGER hotel_reservation_event_immutable BEFORE UPDATE OR DELETE ON "hotel_reservation_events" FOR EACH ROW EXECUTE FUNCTION hotel_reject_immutable_money();

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['hotel_rate_plans','hotel_guests','hotel_reservations','hotel_reservation_stay_units','hotel_room_assignments','hotel_reservation_events','hotel_confirmation_number_sequences','hotel_operation_idempotency_keys','hotel_folios','hotel_folio_postings','hotel_folio_payments','hotel_payment_attempts','hotel_payment_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY hotel_scope ON %I USING ("organizationId"=current_setting(''app.current_organization_id'',true) AND "branchId"=current_setting(''app.current_hotel_property_id'',true)) WITH CHECK ("organizationId"=current_setting(''app.current_organization_id'',true) AND "branchId"=current_setting(''app.current_hotel_property_id'',true))',t); END LOOP; END $$;
CREATE TABLE "hotel_night_audit_runs" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"businessDate" date NOT NULL,"status" "HotelNightAuditStatus" NOT NULL,"currentStep" "HotelNightAuditStep" NOT NULL,"startedAt" timestamptz NOT NULL DEFAULT now(),"startedById" text NOT NULL,"completedAt" timestamptz,"failedAt" timestamptz,"failureCode" text,"failureMessage" text,"summary" jsonb NOT NULL DEFAULT '{}',"version" integer NOT NULL DEFAULT 1,UNIQUE("organizationId","branchId","id"),UNIQUE("organizationId","branchId","businessDate"));
CREATE UNIQUE INDEX hotel_one_running_audit ON "hotel_night_audit_runs"("organizationId","branchId") WHERE status='RUNNING';
CREATE TABLE "hotel_night_audit_step_runs" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"auditRunId" text NOT NULL,"step" "HotelNightAuditStep" NOT NULL,"status" "HotelNightAuditStepStatus" NOT NULL,"attempt" integer NOT NULL DEFAULT 1,"startedAt" timestamptz NOT NULL DEFAULT now(),"completedAt" timestamptz,"result" jsonb NOT NULL DEFAULT '{}',"errorCode" text,"errorMessage" text,UNIQUE("organizationId","branchId","auditRunId","step"));
CREATE TABLE "hotel_daily_snapshots" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"auditRunId" text NOT NULL UNIQUE,"businessDate" date NOT NULL,"roomsAvailable" integer NOT NULL,"roomsOccupied" integer NOT NULL,"roomsOutOfOrder" integer NOT NULL,"arrivals" integer NOT NULL,"departures" integer NOT NULL,"noShows" integer NOT NULL,"roomRevenueMinor" integer NOT NULL,"extrasMinor" integer NOT NULL,"taxMinor" integer NOT NULL,"adjustmentsMinor" integer NOT NULL,"paymentsMinor" integer NOT NULL,"refundsMinor" integer NOT NULL,"closingReceivableMinor" integer NOT NULL,"currency" text NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId","branchId","id"),UNIQUE("organizationId","branchId","businessDate"));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['hotel_night_audit_runs','hotel_night_audit_step_runs','hotel_daily_snapshots'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY hotel_scope ON %I USING ("organizationId"=current_setting(''app.current_organization_id'',true) AND "branchId"=current_setting(''app.current_hotel_property_id'',true)) WITH CHECK ("organizationId"=current_setting(''app.current_organization_id'',true) AND "branchId"=current_setting(''app.current_hotel_property_id'',true))',t); END LOOP; END $$;
CREATE TRIGGER hotel_snapshot_immutable BEFORE UPDATE OR DELETE ON "hotel_daily_snapshots" FOR EACH ROW EXECUTE FUNCTION hotel_reject_immutable_money();
